class HashTable:
    def __init__(self, initial_capacity=8):
        self.capacity = initial_capacity
        self.size = 0
        self.buckets = [[] for _ in range(self.capacity)]  # each bucket is a list for chaining

    def _hash(self, key):
        # Simple hash function using Python's built-in hash, mapped to bucket index
        return hash(key) % self.capacity

    def put(self, key, value):
        index = self._hash(key)
        bucket = self.buckets[index]

        # Check if key already exists in the chain; if so, update
        for i, (k, v) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return

        # Otherwise, insert new key-value pair
        bucket.append((key, value))
        self.size += 1

        # Resize if load factor too high (e.g., > 0.75)
        if self.size / self.capacity > 0.75:
            self._resize(self.capacity * 2)

    def get(self, key):
        index = self._hash(key)
        bucket = self.buckets[index]

        for k, v in bucket:
            if k == key:
                return v
        return None  # or raise KeyError

    def _resize(self, new_capacity):
        old_buckets = self.buckets
        self.capacity = new_capacity
        self.buckets = [[] for _ in range(self.capacity)]
        self.size = 0

        # Rehash all existing key-value pairs into the new buckets
        for bucket in old_buckets:
            for key, value in bucket:
                self.put(key, value)

